import { createForks, teardownForks } from "@tigrisdata/agent-kit";
import { Tigris } from "@tigrisdata/storage";
import { writeFileSync } from "fs";
import { join } from "path";

async function main() {
  const prefix = "eval-prefix";
  const sourceBucket = "source-bucket";
  const forkCount = 3;
  const forksJsonPath = "/home/user/safe-fork/forks.json";

  // 1. Detect prefix collisions
  const tigris = new Tigris();
  const buckets = await tigris.listBuckets();

  const collidingBuckets = buckets.filter(b => b.name.startsWith(prefix));
  console.log(`Found ${collidingBuckets.length} colliding buckets:`, collidingBuckets.map(b => b.name));

  // 2. Delete colliding buckets
  for (const bucket of collidingBuckets) {
    console.log(`Deleting colliding bucket: ${bucket.name}`);
    await tigris.removeBucket(bucket.name);
  }

  // 3. Create forks
  console.log(`Creating ${forkCount} forks for ${sourceBucket} with prefix ${prefix}...`);
  const { data: forkSet, error } = await createForks(sourceBucket, forkCount, {
    prefix: prefix,
    credentials: { role: "Editor" }
  });

  if (error) {
    console.error("Error creating forks:", error);
    process.exit(1);
  }

  if (!forkSet || forkSet.forks.length !== forkCount) {
    console.error(`Expected ${forkCount} forks, but got ${forkSet?.forks.length}`);
    process.exit(1);
  }

  // 4. Record fork names
  const forkNames = forkSet.forks.map(f => f.bucket);
  const output = { forks: forkNames };
  writeFileSync(forksJsonPath, JSON.stringify(output));
  console.log(`Wrote fork names to ${forksJsonPath}:`, output);

  // 5. Tear down the new forks
  console.log("Tearing down forks...");
  await teardownForks(forkSet);
  console.log("Teardown complete.");
}

main().catch(err => {
  console.error("Unhandled error:", err);
  process.exit(1);
});

